// Валидация и подготовка payload для ЮKassa.
// На MVP премиум-маршрут — фиксированная цена 299 RUB.
// Сумма захардкожена на сервере, чтобы фронт не мог её подменить.
const input = $input.first().json;
const body = input.body || input;
const headers = input.headers || {};

const {
  tier = 'premium',
  email = '',
  idempotenceKey = '',
  plannerPayload = null,
  returnUrl = ''
} = body;

if (!email || !String(email).includes('@')) {
  throw new Error('YooKassa create-payment: невалидный email: ' + email);
}
if (tier !== 'premium') {
  throw new Error('YooKassa create-payment: оплата доступна только для premium, получено tier=' + tier);
}
if (!plannerPayload || typeof plannerPayload !== 'object') {
  throw new Error('YooKassa create-payment: не передан plannerPayload с данными формы');
}

// Idempotence-Key обязателен по ЮKassa-API. Если фронт не прислал — генерим сами.
const idempotence = idempotenceKey && String(idempotenceKey).length >= 8
  ? String(idempotenceKey)
  : crypto.randomUUID();

// metadata: до 16 ключей, до 512 символов на значение. Кладём payload как строку.
// На MVP помещаемся: ~300–400 символов.
const plannerPayloadStr = JSON.stringify({ ...plannerPayload, tier: 'premium', email: String(email).trim().toLowerCase() });
if (plannerPayloadStr.length > 510) {
  throw new Error('YooKassa create-payment: plannerPayload слишком длинный (' + plannerPayloadStr.length + ' символов), сократите notes/allergies');
}

const safeReturnUrl = returnUrl && String(returnUrl).startsWith('https://welcomecrimea.ru/')
  ? String(returnUrl)
  : 'https://welcomecrimea.ru/marshrut/oplata/';

const amountValue = '299.00';

const yookassaPayload = {
  amount: { value: amountValue, currency: 'RUB' },
  capture: true,
  confirmation: {
    type: 'redirect',
    return_url: safeReturnUrl
  },
  description: 'AI-маршрут по Крыму, премиум (welcomecrimea.ru)',
  receipt: {
    customer: { email: String(email).trim().toLowerCase() },
    items: [
      {
        description: 'AI-маршрут по Крыму (премиум)',
        quantity: '1.00',
        amount: { value: amountValue, currency: 'RUB' },
        vat_code: 1,
        payment_subject: 'service',
        payment_mode: 'full_payment'
      }
    ]
  },
  metadata: {
    plannerPayload: plannerPayloadStr,
    email: String(email).trim().toLowerCase(),
    source: 'welcomecrimea.ru'
  }
};

return [{
  json: {
    idempotenceKey: idempotence,
    email: String(email).trim().toLowerCase(),
    yookassaPayload
  }
}];
